import {
  isLegacyPeriodAvailable,
  resolveLegacyPeriod,
} from '../../legacyPeriodCompatibility';
import { FilterConfig } from '../types';

export const periodsFilterConfig: FilterConfig = {
  key: 'periods',
  order: 20,
  isCommon: true,
  calculator: (filterData) => {
    return filterData.periods?.default?.value ?? null;
  },
  validator: isLegacyPeriodAvailable,
  dependentDefaultCascadingCalculator: (filterData, currentValues) =>
    resolveLegacyPeriod(filterData, currentValues.periods),
  fallbackCollisionResolver: (
    previousValue,
    currentDefault,
    currentDataFilters,
  ) => {
    return resolveLegacyPeriod(
      currentDataFilters,
      previousValue,
      currentDefault,
    );
  },
  metadata: {
    displayName: 'POS Periods',
    description: 'POS periods filter',
  },
};
